-//   SOLUZIONE 2026-01-28 )
+bool can_read = (p->writer == 0 && p->nreaders < MAX_RW_READERS);
+if (can_read && p->w_writers) {
+	can_read = false;
+}
+if (can_read) {
+	natl pos = rw_find_reader(p, 0);
+	p->readers[pos] = esecuzione->id;
+	p->nreaders++;
+} else {
+	inserimento_lista(p->w_readers, esecuzione);
+	schedulatore();
+}
 }

