+	while (p->w_readers && p->nreaders < MAX_RW_READERS && !p->writer) {
+		des_proc* proc = rimozione_lista(p->w_readers);
+		natl pos = rw_find_reader(p, 0);
+		p->readers[pos] = proc->id;
+		p->nreaders++;
+		inspronti();
+		inserimento_lista(pronti, proc);
+		schedulatore();
+	}
+}

+void rw_activate_writers(des_rw* p) {
+	while (p->w_writers && p->nreaders == 0 && !p->writer) {
+		des_proc* proc = rimozione_lista(p->w_writers);
+		p->writer = proc->id;
+		inspronti();
+		inserimento_lista(pronti, proc);
+		schedulatore();
+	}
+}

 /// Parte C++ della primitiva rw_rel_write()
 extern "C" void c_rw_rel_write(natl rw)
@@ -1987,8 +2023,11 @@ extern "C" void c_rw_rel_write(natl rw)
 		return;
 	}

-// ( SOLUZIONE 2026-01-28
-//   SOLUZIONE 2026-01-28 )
+p->writer = 0;
+rw_activate_readers(p);
+if (!p->w_readers) {
+	rw_activate_writers(p);
+}
 }

 /// Parte C++ della primitiva rw_rel_read()
@@ -2009,8 +2048,12 @@ extern "C" void c_rw_rel_read(natl rw)
 		return;
 	}

-// ( SOLUZIONE 2026-01-28
-//   SOLUZIONE 2026-01-28 )
+	p->readers[pos] = 0;
+	p->nreaders--;
+	rw_activate_writers(p);
+	if (!p->w_writers) {
+		rw_activate_readers(p);
+	}
 }
